INSERT INTO `agent_session` VALUES (1,1,'AGENT_FLOW','Agent备考: 帮我系统复习计算机组成原理Cache直接','PRACTICE_GEN','MEDIUM','{\"history\": [], \"difficulty\": \"MEDIUM\", \"stage_data\": {\"PRACTICE_GEN\": {\"questions\": [{\"q_id\": \"gen-1\", \"stem\": \"关于【帮我系统复习计算机组成原理Cache直接映射与全相联映射】的基本特征，下列说法中正确的是（ ）。\", \"type\": \"choice\", \"score\": 2, \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"text\": \"通过增加硬件成本换取时间复杂度的降低，符合时空权衡思想\"}, {\"key\": \"B\", \"text\": \"在所有极端情况下其时间复杂度均保持恒定不变\"}, {\"key\": \"C\", \"text\": \"无需任何辅助空间即可完成所有边界条件的线性处理\"}, {\"key\": \"D\", \"text\": \"仅能处理顺序存储结构，无法适配链式存储结构\"}]}, {\"q_id\": \"gen-2\", \"stem\": \"在【帮我系统复习计算机组成原理Cache直接映射与全相联映射】的应用场景中，若发生突发边界溢出或命中失效，系统的典型响应机制是（ ）。\", \"type\": \"choice\", \"score\": 2, \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"text\": \"触发软硬件中断或缺页/置换流程，更新页表与 Cache 行\"}, {\"key\": \"B\", \"text\": \"立即终止当前所有进程并重启内核\"}, {\"key\": \"C\", \"text\": \"丢弃后续所有报文且不发送任何确认信号\"}, {\"key\": \"D\", \"text\": \"无条件进入死锁状态等待人工介入\"}]}, {\"q_id\": \"gen-3\", \"stem\": \"【综合应用题】针对【帮我系统复习计算机组成原理Cache直接映射与全相联映射】，请写出其核心判定或处理算法伪代码，并说明：(1)基本设计思想；(2)核心代码实现；(3)时间复杂度与空间复杂度。\", \"type\": \"comprehensive\", \"score\": 10}], \"instruction\": \"已基于【帮我系统复习计算机组成原理Cache直接映射与全相联映射】为您定制针对性测评题（2道核心单选 + 1道应用大题）：\"}, \"KNOWLEDGE_EXPLAIN\": {\"topic\": \"帮我系统复习计算机组成原理Cache直接映射与全相联映射\", \"subject\": \"co\", \"core_concepts\": [{\"title\": \"核心原理与定义\", \"detail\": \"针对【帮我系统复习计算机组成原理Cache直接映射与全相联映射】，408 统考重点考查其底层工作机理、数据结构转换以及时间/空间折中考虑。\"}, {\"title\": \"408 历年常考陷阱\", \"detail\": \"注意分清直接映射与组相联的行号计算、TCP 确认号语义（期望收到的下一字节序号）及树转二叉树的孩子兄弟表示法边界。\"}, {\"title\": \"解题公式与速记口诀\", \"detail\": \"大题先写设计思想，代码写注释并判空，复杂度给出大O渐进阶；客观题注意首尾项加一减一细节。\"}], \"recommended_flow\": \"认真阅读精讲要点后，点击【开始针对性自测】，AI 将根据当前知识点生成 3 道诊断习题。\"}}, \"instruction\": \"帮我系统复习计算机组成原理Cache直接映射与全相联映射\", \"target_subject\": \"co\"}','2026-11-09 15:49:28','2026-11-09 15:49:45'),(2,1,'AGENT_FLOW','Agent备考: 1','KNOWLEDGE_EXPLAIN','MEDIUM','{\"history\": [], \"difficulty\": \"MEDIUM\", \"stage_data\": {\"KNOWLED