CREATE TABLE `agent_task_execution` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务执行记录ID',
  `session_id` bigint NOT NULL COMMENT '关联会话ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `instruction` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户发起的自然语言复习指令 (如: "今天帮我复习计网TCP滑动窗口和拥塞控制，并生成自测")',
  `target_subject` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标学科: ds, co, os, cn',
  `target_knowledge_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标知识点ID',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'RUNNING' COMMENT '状态: PENDING(等待), RUNNING(运行中), PAUSED(暂停), COMPLETED(已完成), FAILED(失败)',
  `generated_questions_json` json DEFAULT NULL COMMENT '本次任务AI生成的专项练习题目ID列表',
  `drill_exam_ids_json` json DEFAULT NULL COMMENT '本次任务自动调取的历年相关真题ID列表',
  `report_content` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '任务完结后生成的全流程复习总结报告',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_task` (`user_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent智能备考任务自动化调度执行表';
/*!40101 SET character_set_client = @saved_cs_client */;

