  `title` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '试卷标题 (如: 2024年全国硕士研究生招生考试408真题)',
  `total_score` int DEFAULT '150' COMMENT '总分 (408满分150)',
