  `question_count` int DEFAULT '47' COMMENT '总题数 (单选40题+综合7题)',
  `paper_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'TRUE_EXAM' COMMENT '试卷类型: TRUE_EXAM(历年真题), MOCK(全真模拟), AI_CUSTOM(智能生成)',
  `status` tinyint DEFAULT '1' COMMENT '状态: 1启用 0禁用',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_year_type` (`year`,`paper_type`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='408试卷主表';
