DROP TABLE IF EXISTS `exam_question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exam_question` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题目全局唯一ID (如: 2024-1, 2024-41)',
  `paper_id` bigint DEFAULT NULL COMMENT '所属试卷ID',
  `year` int NOT NULL COMMENT '真题年份',
  `question_number` int NOT NULL COMMENT '题号 (1~47)',
  `score` int NOT NULL COMMENT '分值 (单选通常2分，大题8~15分)',
  `question_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题型: choice(单选题), comprehensive(综合应用大题), algorithm(算法设计)',
  `subject_code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属学科: ds, co, os, cn',
  `chapter_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属章节名',
  `stem` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题干内容 (支持Markdown、LaTeX公式、代码块及插图)',
  `options_json` json DEFAULT NULL COMMENT '选择题选项列表 [{"key":"A","text":"..."}, ...]',
  `answer` text COLLATE utf8mb4_unicode_ci COMMENT '标准参考答案 (选择题如"D"，主观大题为标准参考答案或核心算法代码)',
  `difficulty` int DEFAULT '3' COMMENT '难度等级 (1:简单 ~ 5:极难)',
  `tags_json` json DEFAULT NULL COMMENT '考查考点标签 ["数据结构", "图", "拓扑排序"]',
  `explanation` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '详尽答案解析与考点精解',
  `exam_point_analysis` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '命题意图、采分思路及易错陷阱',
  `resource_links_json` json DEFAULT NULL COMMENT '关联的课本参考与拓展文献链接',
  `is_variant` tinyint DEFAULT '0' COMMENT '是否为AI变式题: 0真题原题 1变式演练题',
  `parent_question_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '若为变式题，对应所衍生的原真题ID',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_year_subject` (`year`,`subject_code`),
  KEY `idx_subject_chapter` (`subject_code`,`chapter_name`),
  KEY `idx_parent_question` (`parent_question_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='408真题及题库主表';
