--
-- Table structure for table `exam_question_sub`
--

DROP TABLE IF EXISTS `exam_question_sub`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exam_question_sub` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '子题主键ID',
  `question_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主试题ID (关联exam_question)',
  `sub_number` int NOT NULL COMMENT '小问序号 (如第1问、第2问)',
  `sub_stem` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '小问要求与题干 (如: "(1) 给出算法的基本设计思想。（4 分）")',
  `score` int NOT NULL COMMENT '该小问分值',
  `standard_answer` text COLLATE utf8mb4_unicode_ci COMMENT '小问参考答案与评分标准',
  `rubric_points_json` json DEFAULT NULL COMMENT '智能批改采分点规则列表 [{"point_id":1, "desc":"基本思想完整度", "score":4}, ...]',
  PRIMARY KEY (`id`),
  KEY `idx_question_sub` (`question_id`,`sub_number`)
) ENGINE=InnoDB AUTO_INCREMENT=249 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='408大题小问及智能采分点配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `exam_question_sub`
--

LOCK TABLES `exam_question_sub` WRITE;
