DROP TABLE IF EXISTS `k_chapter`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `k_chapter` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '章节标识 (如: chapter-ds-1, 线性表)',
  `subject_code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属科目: ds, co, os, cn',
  `title` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '章节标题',
  `chapter_number` int DEFAULT '1' COMMENT '章序号',
  `layer` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属大类层级',
  `sort_order` int DEFAULT '0' COMMENT '展示排序',
  PRIMARY KEY (`id`),
  KEY `idx_subject` (`subject_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识体系-章节表';
/*!40101 SET character_set_client = @saved_cs_client */;

