--
-- Table structure for table `k_point`
--

DROP TABLE IF EXISTS `k_point`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `k_point` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '知识块/考点ID (与题目关联的 knowledgeBlockId: kb-*)',
  `section_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属小节ID',
  `title` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '知识点标题 (如: 单链表的插入与删除)',
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT '考点摘要',
  `importance` int DEFAULT '3' COMMENT '考查重要度: 1-5星',
  `exam_frequency` int DEFAULT '0' COMMENT '历年考查频次(历年真题命中数)',
  `tags_json` json DEFAULT NULL COMMENT '标签列表 (JSON字符串数组)',
  `sort_order` int DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_section` (`section_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识体系-考点/知识块表';
/*!40101 SET character_set_client = @saved_cs_client */;

