DROP TABLE IF EXISTS `k_section`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `k_section` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '小节标识 (如: section-ds-1-1)',
  `chapter_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属章节ID',
  `title` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '小节标题 (如: 顺序表与链表)',
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT '小节概述',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  PRIMARY KEY (`id`),
  KEY `idx_chapter` (`chapter_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识体系-小节表';
/*!40101 SET character_set_client = @saved_cs_client */;

