INSERT INTO `k_subject` VALUES ('CO','计算机组成原理','Cpu',2,'408统考核心学科，占比45分。涵盖机器数表示与浮点运算、Cache-主存组相联映射、CPU数据通路与指令流水线、中断与DMA。'),('DS','数据结构','Code2',1,'408统考核心学科，占比45分。涵盖线性表、树与二叉树、图论算法、查找与高级树、排序时空复杂度。'),('NET','计算机网络','Globe2',4,'408统考核心学科，占比25分。涵盖体系结构与时延、滑动窗口与CSMA/CD、CIDR子网划分与路由协议、TCP握手挥手与拥塞控制。'),('OS','操作系统','Layers',3,'408统考核心学科，占比35分。涵盖系统调用双核态、进程线程状态、信号量PV同步、请求分页虚存管理、文件系统与磁盘调度。');
/*!40000 ALTER TABLE `k_subject` ENABLE KEYS */;
