DROP TABLE IF EXISTS `kb_chunk`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kb_chunk` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '切片ID',
  `document_id` bigint NOT NULL COMMENT '关联文档ID',
  `chunk_index` int NOT NULL COMMENT '切片序号',
  `content` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '切片文本内容',
  `token_count` int DEFAULT '0' COMMENT 'Token估算长度',
  `page_number` int DEFAULT NULL COMMENT 'PDF对应原始页码',
  `bbox_json` json DEFAULT NULL COMMENT '原始页面位置坐标 (用于前端高亮溯源)',
  `image_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '切片关联的原理图/图表URL',
  `vector_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '向量数据库中关联的ID (如Chroma/Milvus)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_doc_chunk` (`document_id`,`chunk_index`),
  KEY `idx_vector_id` (`vector_id`)
) ENGINE=InnoDB AUTO_INCREMENT=591 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RAG文档切片及向量映射表';
/*!40101 SET character_set_client = @saved_cs_client */;

