--
-- Table structure for table `test_answer_detail`
--

DROP TABLE IF EXISTS `test_answer_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `test_answer_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '答题明细ID',
  `test_record_id` bigint NOT NULL COMMENT '所属测试记录ID',
  `question_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '试题ID',
  `sub_question_id` bigint DEFAULT NULL COMMENT '小问ID (若大题含小问)',
  `user_answer` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '用户作答内容 (选择题为A/B/C/D，大题为文字/代码/拍照图片URL)',
  `is_correct` tinyint DEFAULT NULL COMMENT '是否正确: 1正确 0错误 (针对客观选择题)',
  `score_earned` decimal(5,2) DEFAULT '0.00' COMMENT '本题实得分',
  `ai_feedback` text COLLATE utf8mb4_unicode_ci COMMENT 'AI智能阅卷综合评语',
  `missing_points_json` json DEFAULT NULL COMMENT '答题中遗漏的核心考查要点 (JSON数组)',
  `error_analysis` text COLLATE utf8mb4_unicode_ci COMMENT '错误表述与概念混淆原因诊断',
  `rubric_matched_json` json DEFAULT NULL COMMENT '采分点命中详情 [{"rubric_id":1, "hit":true, "score":2, "reason":"正确描述拓扑排序流程"}, ...]',
  `optimization_advice` text COLLATE utf8mb4_unicode_ci COMMENT '解题规范与得分优化建议',
  `graded_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'SYSTEM_AUTO' COMMENT '判分方式: SYSTEM_AUTO(系统自动对比), AI_AGENT(智能体采分点精批), MANUAL(人工复核)',
  `graded_at` datetime DEFAULT NULL COMMENT '批改完成时间',
  PRIMARY KEY (`id`),
  KEY `idx_record_q` (`test_record_id`,`question_id`),
  KEY `idx_q_correct` (`question_id`,`is_correct`)
) ENGINE=InnoDB AUTO_INCREMENT=223 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考生单题答题与采分点批改详情表';
/*!40101 SET character_set_client = @saved_cs_client */;

