DROP TABLE IF EXISTS `test_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `test_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '测试记录ID',
  `user_id` bigint NOT NULL COMMENT '测评用户ID',
  `paper_id` bigint DEFAULT NULL COMMENT '试卷ID (可选)',
  `test_title` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测评标题 (如: 2024年408全真模考)',
  `test_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测评模式: FULL_MOCK(全真模拟), CHAPTER_DRILL(章节专练), WEAKNESS_PUSH(薄弱专项), AI_CUSTOM(智能组卷)',
  `subject_code` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '若为单科测试(ds,co,os,cn)，全科为NULL',
  `total_score` int DEFAULT '150' COMMENT '满分值',
  `user_score` decimal(5,2) DEFAULT NULL COMMENT '用户最终得分',
  `time_spent_seconds` int DEFAULT '0' COMMENT '答题消耗时长(秒)',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'IN_PROGRESS' COMMENT '状态: IN_PROGRESS(作答中), SUBMITTED(判分中), GRADED(已批阅完成)',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `submit_time` datetime DEFAULT NULL COMMENT '交卷时间',
  `ai_report_summary` text COLLATE utf8mb4_unicode_ci COMMENT 'AI生成的整卷测评学情总结分析',
  `weak_points_json` json DEFAULT NULL COMMENT '本次测评暴露出的薄弱考点集合 (JSON数组)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_test` (`user_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自测与模拟考试记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

