DROP TABLE IF EXISTS `user_knowledge_mastery`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_knowledge_mastery` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `knowledge_block_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '考点知识块ID (kb-*)',
  `subject_code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属学科: ds, co, os, cn',
  `total_attempts` int DEFAULT '0' COMMENT '做题总次数',
  `correct_attempts` int DEFAULT '0' COMMENT '做对总次数',
  `accuracy_rate` decimal(5,2) DEFAULT '0.00' COMMENT '正确率 (百分比 0.00% ~ 100.00%)',
  `mastery_level` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'UNLEARNED' COMMENT '掌握等级: UNLEARNED(未学), WEAK(薄弱), FAMILIAR(熟悉), MASTERED(精通)',
  `weakness_score` decimal(5,2) DEFAULT '0.00' COMMENT '薄弱度综合加权得分 (用于热力图与推荐推送加权)',
  `last_practiced_at` datetime DEFAULT NULL COMMENT '最后练习时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_kb` (`user_id`,`knowledge_block_id`),
  KEY `idx_user_mastery` (`user_id`,`subject_code`,`mastery_level`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户408考点掌握度画像与薄弱点图谱表';
