  `user_id` bigint NOT NULL COMMENT '用户ID',
  `title` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '笔记标题',
  `subject_code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '科目代号: ds, co, os, cn',
  `content_md` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '富文本笔记Markdown正文 (支持公式、流程图、插图)',
  `tags_json` json DEFAULT NULL COMMENT '笔记分类标签列表 (JSON数组)',
  `related_knowledge_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联的知识块ID',
  `related_question_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联的真题ID (若为做题心得)',
  `excerpt_source` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源摘录出处 (如: 2024年408真题第41题答案解析)',
  `is_ai_summarized` tinyint DEFAULT '0' COMMENT '是否经过AI精简浓缩: 1是 0否',
  `ai_summary` text COLLATE utf8mb4_unicode_ci COMMENT 'AI生成的考前核心速记摘要',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_note_sub` (`user_id`,`subject_code`),
  KEY `idx_note_kb` (`related_knowledge_id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考生个人笔记与知识摘录表';
