--
-- Table structure for table `user_wrong_question_backup`
--

DROP TABLE IF EXISTS `user_wrong_question_backup`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_wrong_question_backup` (
  `id` bigint NOT NULL DEFAULT '0' COMMENT '错题主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `question_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联真题/内置试题ID (为NULL时表示手动拍照录入)',
  `custom_question_json` json DEFAULT NULL COMMENT '手动拍照上传的题目数据 (含图片URL、OCR识别文本、手填答案与解析)',
  `subject_code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '科目代号 (ds, co, os, cn)',
  `knowledge_block_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主要考点ID',
  `source_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'TEST' COMMENT '来源: TEST(模拟模考), PRACTICE(专项练习), MANUAL_UPLOAD(手动拍照上传), AI_DIAG(Agent复习诊断)',
  `wrong_count` int DEFAULT '1' COMMENT '累计做错次数',
  `master_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'UNMASTERED' COMMENT '掌握状态: UNMASTERED(未掌握), REVIEWING(复习中), MASTERED(已攻克)',
  `error_reason_tag` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'CONCEPT_CONFUSION' COMMENT '错误归因: CONCEPT_CONFUSION(概念混淆), CALCULATION_ERROR(计算失误), MEMORY_LAPSE(公式记忆模糊), CODE_BUG(算法逻辑缺陷), CARELESS(审题不清), OTHER(其他)',
  `user_notes` text COLLATE utf8mb4_unicode_ci COMMENT '考生错题自省与心得复盘笔记',
  `last_wrong_answer` text COLLATE utf8mb4_unicode_ci COMMENT '最近一次错误作答',
  `last_practiced_at` datetime DEFAULT NULL COMMENT '最后重做时间',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `user_wrong_question_backup`
